from __future__ import absolute_import, division, print_function,\
    unicode_literals

from builtins import int, object
import time
import re
import socket
import struct
from taf.ul.trs_e2e_fw.lib.call_utils.dongle.exceptions import DongleNotAttachedException, IPAddressNotAssigned, ATCommandFailedException
from taf.ul.trs_e2e_fw.lib.call_utils.dongle.serial_access import Serial_Access
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from future import standard_library

logger = BackgroundLogger.Instance()
standard_library.install_aliases()


class AT(object):

    def __init__(self, ssh_session, cli_utils_obj, rat, dongle_config_name, apn):
        self.device_path = None
        self.rat = rat
        self.dongle_config_name = dongle_config_name
        self.ssh_session = ssh_session
        self.apn = apn
        self.cli_utils = cli_utils_obj
        self.serial_2tcp_session = Serial_Access(ssh_session)

    def attach(self):
        self.cli_utils.check_dongle_is_detected()
        self.ue_ip, netmask, self.gw_ip = self._run_attach_sequence_at_commands()
        time.sleep(10)
        logger.info("UE IP: {}, netmask: {}, gateway IP: {}".format(self.ue_ip, netmask, self.gw_ip))
        return self.ue_ip, self.gw_ip

    def detach(self):
        self.run_detach_sequence_at_commands()
        self.cli_utils.delete_route(self.ue_ip, self.gw_ip)
        # Catch exception and ignore
        # Verify IP
        # self.cli_utils.flush_interface()

    def _run_attach_sequence_at_commands(self, reattach=True, max_attempts=2):
        attempt = 1
        while attempt <= max_attempts:
            logger.info('Attach AT commands attempt: {} '.format(attempt))
            try:
                with self.serial_2tcp_session.new_serial_2tcp_connection(self.rat, self.dongle_config_name):
                    logger.debug("AT commands starting")
                    self._run_AT_command('at', max_attempts=3)
                    # Check if basic AT command is responding
                    self._run_AT_command('at+cfun?')
                    self._run_AT_command('at+cfun=0')
                    self._run_AT_command('at+cgdcont=2, "IP", "{}"'.format(self.apn))
                    self._run_AT_command('at+cfun=1')
                    # time.sleep(30)
                    self._send_and_validate_attach_at_command(reattach)
                    self._run_AT_command('at^ndisdup=1,1')
                    return self._get_ip_params()
            except Exception:
                attempt += 1
                time.sleep(5)
        raise DongleNotAttachedException

    def run_detach_sequence_at_commands(self):
        self.device_path = self.cli_utils.check_dongle_is_detected(self.rat, self.dongle_config_name)
        with self.serial_2tcp_session.new_serial_2tcp_connection():
            # Check if serial connection can be opened again or needs opened connection
            self._run_AT_command('at', max_attempts=3)
            # Check if basic AT command is responding
            self._run_AT_command('at+cfun?')
            self._run_AT_command('at+cfun=0')

    def _send_and_validate_attach_at_command(self, reattach):
        self._run_AT_command('at+cgatt?')
        # if reattach:
        #     self._run_AT_command('at+cgatt=0', max_attempts=2)
        self._run_AT_command('at+cgatt=1', max_attempts=2)
        attach_cmd_output = self._run_AT_command('at+cgatt?')
        self._verify_if_attach_succeeded(attach_cmd_output)

    def _verify_if_attach_succeeded(self, attach_cmd_output):
        attach_success_message = 'OK'
        if attach_success_message not in attach_cmd_output:
            raise DongleNotAttachedException
        return True

    def _get_network_assigned_ipaddress(self):
        console_output = self._run_AT_command('at+cgpaddr=1')
        match_list = re.findall(r'\d+\.\d+\.\d+\.\d+', console_output)
        if len(match_list) > 0:
            return match_list[0]
        raise IPAddressNotAssigned

    def _get_ip_params(self):
        ue_ip, netmask, gw_ip = '', '', ''
        result = self._run_AT_command('at^dhcp?', max_attempts=3)
        if 'dhcp:' not in result.lower():
            logger.error('dhcp not found in result')
            raise
        lines = result.split('\n')
        for line in lines:
            if 'dhcp:' in line.lower():
                param_list = line.split(':')[1].split(',')
                ue_ip = self._convert_hex_to_ip(param_list[0])
                netmask = self._convert_hex_to_ip(param_list[1])
                gw_ip = self._convert_hex_to_ip(param_list[2])
                match_list = re.findall(r'\d+\.\d+\.\d+\.\d+', ue_ip)
                if len(match_list) == 0:
                    raise IPAddressNotAssigned('dhcp at command did not return IP')
                break
        return ue_ip, netmask, gw_ip

    def _run_AT_command(self, command, max_attempts=2):
        attempt = 1
        while attempt <= max_attempts:
            console_output = self.serial_2tcp_session.write_command_and_return_output(command)
            logger.debug("AT command output: {}".format(console_output))
            if 'OK' in console_output:
                time.sleep(5)
                return console_output
            else:
                attempt += 1
                time.sleep(5)  # Sleep for sometime before next attempt
        raise ATCommandFailedException

    def _convert_hex_to_ip(self, param):
        addr_long = int(param, 16)
        hex_ip = struct.pack("<L", addr_long)
        return socket.inet_ntoa(hex_ip)
